// LeetCode 1143 LCS with two rows: O(m * n) time, O(n) space.
function longestCommonSubsequence(a, b) {
  let prev = new Array(b.length + 1).fill(0);
  for (let i = 1; i <= a.length; i++) {
    const cur = new Array(b.length + 1).fill(0);
    for (let j = 1; j <= b.length; j++) {
      cur[j] = a[i - 1] === b[j - 1] ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
    }
    prev = cur;
  }
  return prev[b.length];
}

// LeetCode 72 Edit Distance, full table for clarity.
function minDistance(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, (_, i) => {
    const row = new Array(n + 1).fill(0);
    row[0] = i;                                  // delete all i chars
    return row;
  });
  for (let j = 0; j <= n; j++) dp[0][j] = j;     // insert all j chars
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1]
        : 1 + Math.min(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1]);
  return dp[m][n];
}

def lcs(a, b):
    """Returns (length, one LCS string). O(m * n) time and space."""
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    out, i, j = [], m, n                       # walk back to recover the string
    while i and j:
        if a[i - 1] == b[j - 1]:
            out.append(a[i - 1])
            i, j = i - 1, j - 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return dp[m][n], "".join(reversed(out))

def edit_distance(a, b):
    """Levenshtein distance with one rolling row. O(m * n) time, O(n) space."""
    m, n = len(a), len(b)
    prev = list(range(n + 1))                  # row for the empty prefix of a
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j - 1],  # replace
                                 prev[j],      # delete from a
                                 cur[j - 1])   # insert into a
        prev = cur
    return prev[n]

def is_match(s, p):
    """LeetCode 10 Regular Expression Matching ('.' and '*')."""
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(2, n + 1):                  # empty s vs patterns like a*b*
        dp[0][j] = p[j - 1] == "*" and dp[0][j - 2]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == "*":
                zero = dp[i][j - 2]
                one_more = p[j - 2] in (s[i - 1], ".") and dp[i - 1][j]
                dp[i][j] = zero or one_more
            else:
                dp[i][j] = p[j - 1] in (s[i - 1], ".") and dp[i - 1][j - 1]
    return dp[m][n]

// LeetCode 72 Edit Distance with one row and a saved diagonal: O(n) space.
static int minDistance(String a, String b) {
    int m = a.length(), n = b.length();
    int[] dp = new int[n + 1];
    for (int j = 0; j <= n; j++) dp[j] = j;
    for (int i = 1; i <= m; i++) {
        int diag = dp[0];                 // dp[i-1][0]
        dp[0] = i;
        for (int j = 1; j <= n; j++) {
            int up = dp[j];               // dp[i-1][j]
            if (a.charAt(i - 1) == b.charAt(j - 1)) dp[j] = diag;
            else dp[j] = 1 + Math.min(diag, Math.min(up, dp[j - 1]));
            diag = up;
        }
    }
    return dp[n];
}

// LeetCode 115 Distinct Subsequences, 1-D, iterate j backwards.
static int numDistinct(String s, String t) {
    long[] dp = new long[t.length() + 1];
    dp[0] = 1;
    for (int i = 1; i <= s.length(); i++)
        for (int j = t.length(); j >= 1; j--)
            if (s.charAt(i - 1) == t.charAt(j - 1)) dp[j] += dp[j - 1];
    return (int) dp[t.length()];
}

// LeetCode 97 Interleaving String: dp[j] = can s1[0..i) and s2[0..j) form s3[0..i+j).
bool isInterleave(const string& s1, const string& s2, const string& s3) {
    int m = s1.size(), n = s2.size();
    if (m + n != (int)s3.size()) return false;
    vector<bool> dp(n + 1, false);
    for (int i = 0; i <= m; i++)
        for (int j = 0; j <= n; j++) {
            if (i == 0 && j == 0) { dp[j] = true; continue; }
            bool fromS1 = i > 0 && dp[j] && s1[i - 1] == s3[i + j - 1];
            bool fromS2 = j > 0 && dp[j - 1] && s2[j - 1] == s3[i + j - 1];
            dp[j] = fromS1 || fromS2;
        }
    return dp[n];
}

// LeetCode 516 Longest Palindromic Subsequence, full interval table.
function longestPalindromeSubseq(s) {
  const n = s.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = n - 1; i >= 0; i--) {          // fill by decreasing i ...
    dp[i][i] = 1;
    for (let j = i + 1; j < n; j++) {         // ... and increasing j
      dp[i][j] = s[i] === s[j]
        ? dp[i + 1][j - 1] + 2
        : Math.max(dp[i + 1][j], dp[i][j - 1]);
    }
  }
  return n ? dp[0][n - 1] : 0;
}

// LeetCode 647 Palindromic Substrings with the boolean table.
function countSubstrings(s) {
  const n = s.length;
  const pal = Array.from({ length: n }, () => new Array(n).fill(false));
  let count = 0;
  for (let i = n - 1; i >= 0; i--)
    for (let j = i; j < n; j++)
      if (s[i] === s[j] && (j - i < 2 || pal[i + 1][j - 1])) { pal[i][j] = true; count++; }
  return count;
}

def min_cut(s):
    """LeetCode 132 Palindrome Partitioning II: pal table + cut DP, O(n^2)."""
    n = len(s)
    pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):              # i descending so pal[i+1] is ready
        for j in range(i, n):
            pal[i][j] = s[i] == s[j] and (j - i < 2 or pal[i + 1][j - 1])
    cuts = [0] * n
    for j in range(n):
        if pal[0][j]:
            continue                            # whole prefix is a palindrome
        cuts[j] = min(cuts[i - 1] + 1 for i in range(1, j + 1) if pal[i][j])
    return cuts[-1]

def longest_palindrome_subseq(s):
    """LeetCode 516, interval DP with one rolling row. O(n^2) time, O(n) space."""
    n = len(s)
    dp = [0] * n                                # dp[j] holds row i+1 before update
    for i in range(n - 1, -1, -1):
        new = [0] * n
        new[i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                new[j] = dp[j - 1] + 2          # dp[i+1][j-1]
            else:
                new[j] = max(dp[j], new[j - 1]) # dp[i+1][j], dp[i][j-1]
        dp = new
    return dp[n - 1] if n else 0

def min_insertions(s):
    """LeetCode 1312: n minus the longest palindromic subsequence."""
    return len(s) - longest_palindrome_subseq(s)

// LeetCode 132 Palindrome Partitioning II.
static int minCut(String s) {
    int n = s.length();
    boolean[][] pal = new boolean[n][n];
    int[] cuts = new int[n];
    for (int j = 0; j < n; j++) {
        cuts[j] = j;                                     // worst case: cut every char
        for (int i = 0; i <= j; i++) {
            if (s.charAt(i) == s.charAt(j) && (j - i < 2 || pal[i + 1][j - 1])) {
                pal[i][j] = true;                        // pal[i+1][j-1] was set in column j-1
                cuts[j] = (i == 0) ? 0 : Math.min(cuts[j], cuts[i - 1] + 1);
            }
        }
    }
    return cuts[n - 1];
}

// Classic 0/1 knapsack, one row. Capacity loop goes DOWN so each item is used once.
function knapsack01(weights, values, W) {
  const dp = new Array(W + 1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i], v = values[i];
    for (let c = W; c >= w; c--) dp[c] = Math.max(dp[c], dp[c - w] + v);
  }
  return dp[W];
}

// LeetCode 416 Partition Equal Subset Sum.
function canPartition(nums) {
  const total = nums.reduce((a, b) => a + b, 0);
  if (total % 2) return false;
  const target = total / 2;
  const can = new Array(target + 1).fill(false);
  can[0] = true;
  for (const x of nums)
    for (let s = target; s >= x; s--) if (can[s - x]) can[s] = true;
  return can[target];
}

// LeetCode 494 Target Sum: count subsets with sum P = (total + target) / 2.
function findTargetSumWays(nums, target) {
  const total = nums.reduce((a, b) => a + b, 0);
  if (Math.abs(target) > total || (total + target) % 2) return 0;
  const P = (total + target) / 2;
  const ways = new Array(P + 1).fill(0);
  ways[0] = 1;
  for (const x of nums)
    for (let s = P; s >= x; s--) ways[s] += ways[s - x];
  return ways[P];
}

def knapsack_01(weights, values, W):
    dp = [0] * (W + 1)
    for w, v in zip(weights, values):
        for c in range(W, w - 1, -1):          # backwards: each item at most once
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[W]

def can_partition_bitset(nums):
    """LeetCode 416 with a big-int bitset: bit s set means sum s is reachable."""
    total = sum(nums)
    if total % 2:
        return False
    bits = 1
    for x in nums:
        bits |= bits << x
    return (bits >> (total // 2)) & 1 == 1

def find_max_form(strs, m, n):
    """LeetCode 474 Ones and Zeroes: 2-D weight, both loops backwards."""
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for s in strs:
        zeros, ones = s.count("0"), s.count("1")
        for z in range(m, zeros - 1, -1):
            for o in range(n, ones - 1, -1):
                dp[z][o] = max(dp[z][o], dp[z - zeros][o - ones] + 1)
    return dp[m][n]

def last_stone_weight_ii(stones):
    """LeetCode 1049: closest subset sum to total / 2."""
    total = sum(stones)
    half = total // 2
    can = [True] + [False] * half
    for x in stones:
        for s in range(half, x - 1, -1):
            can[s] = can[s] or can[s - x]
    best = max(s for s in range(half + 1) if can[s])
    return total - 2 * best

// LeetCode 416 Partition Equal Subset Sum, O(n * target) time, O(target) space.
static boolean canPartition(int[] nums) {
    int total = 0;
    for (int x : nums) total += x;
    if (total % 2 != 0) return false;
    int target = total / 2;
    boolean[] can = new boolean[target + 1];
    can[0] = true;
    for (int x : nums)
        for (int s = target; s >= x; s--)
            can[s] |= can[s - x];
    return can[target];
}

// LeetCode 416 with std::bitset: each shift-or processes many sums per machine word.
// Sum of nums is at most 200 * 100 = 20000 on LeetCode.
bool canPartition(const vector<int>& nums) {
    int total = accumulate(nums.begin(), nums.end(), 0);
    if (total % 2) return false;
    bitset<20001> bits;
    bits[0] = 1;
    for (int x : nums) bits |= bits << x;
    return bits[total / 2];
}

// LeetCode 518 Coin Change II: combinations -> coins in the OUTER loop.
function change(amount, coins) {
  const ways = new Array(amount + 1).fill(0);
  ways[0] = 1;
  for (const coin of coins)
    for (let a = coin; a <= amount; a++) ways[a] += ways[a - coin];
  return ways[amount];
}

// LeetCode 377 Combination Sum IV: ordered sequences -> amount in the OUTER loop.
function combinationSum4(nums, target) {
  const ways = new Array(target + 1).fill(0);
  ways[0] = 1;
  for (let a = 1; a <= target; a++)
    for (const x of nums) if (x <= a) ways[a] += ways[a - x];
  return ways[target];
}

// LeetCode 279 Perfect Squares: unbounded min-knapsack over 1, 4, 9, ...
function numSquares(n) {
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;
  for (let k = 1; k * k <= n; k++) {
    const sq = k * k;
    for (let x = sq; x <= n; x++) dp[x] = Math.min(dp[x], dp[x - sq] + 1);
  }
  return dp[n];
}

// LeetCode 518 Coin Change II.
static int change(int amount, int[] coins) {
    int[] ways = new int[amount + 1];
    ways[0] = 1;
    for (int coin : coins)
        for (int a = coin; a <= amount; a++) ways[a] += ways[a - coin];
    return ways[amount];
}

// LeetCode 377 Combination Sum IV. Intermediate counts can exceed int range
// even though the final answer fits, so accumulate in long and cap.
static int combinationSum4(int[] nums, int target) {
    long[] ways = new long[target + 1];
    ways[0] = 1;
    for (int a = 1; a <= target; a++)
        for (int x : nums)
            if (x <= a) ways[a] = Math.min(Integer.MAX_VALUE, ways[a] + ways[a - x]);
    return (int) ways[target];
}

// LeetCode 322 Coin Change (fewest coins).
int coinChange(const vector<int>& coins, int amount) {
    vector<int> dp(amount + 1, amount + 1);    // amount + 1 acts as infinity
    dp[0] = 0;
    for (int c : coins)
        for (int a = c; a <= amount; a++)
            dp[a] = min(dp[a], dp[a - c] + 1);
    return dp[amount] > amount ? -1 : dp[amount];
}

// LeetCode 377 Combination Sum IV with unsigned arithmetic (wraps instead of UB).
int combinationSum4(const vector<int>& nums, int target) {
    vector<unsigned long long> ways(target + 1, 0);
    ways[0] = 1;
    for (int a = 1; a <= target; a++)
        for (int x : nums)
            if (x <= a) ways[a] += ways[a - x];
    return (int)ways[target];
}

// LeetCode 312 Burst Balloons. dp[i][j] = best for balloons strictly inside (i, j).
function maxCoins(nums) {
  const v = [1, ...nums, 1], n = v.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let len = 2; len < n; len++) {
    for (let i = 0; i + len < n; i++) {
      const j = i + len;
      for (let k = i + 1; k < j; k++)
        dp[i][j] = Math.max(dp[i][j], dp[i][k] + v[i] * v[k] * v[j] + dp[k][j]);
    }
  }
  return dp[0][n - 1];
}

from functools import cache

def max_coins(nums):
    """LeetCode 312 Burst Balloons, bottom-up by interval length. O(n^3)."""
    vals = [1] + nums + [1]
    n = len(vals)
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n):                 # j - i = length
        for i in range(0, n - length):
            j = i + length
            best = 0
            for k in range(i + 1, j):          # k bursts last inside (i, j)
                cand = dp[i][k] + vals[i] * vals[k] * vals[j] + dp[k][j]
                if cand > best:
                    best = cand
            dp[i][j] = best
    return dp[0][n - 1]

def min_cost_cut_stick(n, cuts):
    """LeetCode 1547, memoised: pick the first cut in each segment."""
    pts = [0] + sorted(cuts) + [n]

    @cache
    def solve(i, j):                           # cost to make all cuts strictly between pts[i], pts[j]
        if j - i < 2:
            return 0
        return pts[j] - pts[i] + min(solve(i, k) + solve(k, j) for k in range(i + 1, j))

    return solve(0, len(pts) - 1)

def predict_the_winner(nums):
    """LeetCode 486: dp[i][j] = best score difference for the player to move."""
    n = len(nums)
    dp = nums[:]                               # length-1 intervals
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i] = max(nums[i] - dp[i + 1], nums[j] - dp[i])
    return dp[0] >= 0

// LeetCode 312 Burst Balloons, iterate i downwards and j upwards.
static int maxCoins(int[] nums) {
    int n = nums.length + 2;
    int[] v = new int[n];
    v[0] = v[n - 1] = 1;
    for (int i = 0; i < nums.length; i++) v[i + 1] = nums[i];
    int[][] dp = new int[n][n];
    for (int i = n - 3; i >= 0; i--)
        for (int j = i + 2; j < n; j++)
            for (int k = i + 1; k < j; k++)
                dp[i][j] = Math.max(dp[i][j], dp[i][k] + v[i] * v[k] * v[j] + dp[k][j]);
    return dp[0][n - 1];
}

// Matrix-chain multiplication: dims has n + 1 entries for n matrices.
// dp[i][j] = min scalar multiplications to compute A_i .. A_j (closed range).
long long matrixChain(const vector<int>& dims) {
    int n = dims.size() - 1;
    vector<vector<long long>> dp(n, vector<long long>(n, 0));
    for (int len = 2; len <= n; len++)
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            dp[i][j] = LLONG_MAX;
            for (int k = i; k < j; k++)
                dp[i][j] = min(dp[i][j],
                               dp[i][k] + dp[k + 1][j] + 1LL * dims[i] * dims[k + 1] * dims[j + 1]);
        }
    return dp[0][n - 1];
}

// LeetCode 337 House Robber III. Returns [robThis, skipThis].
function rob(root) {
  const dfs = (node) => {
    if (!node) return [0, 0];
    const [lr, ls] = dfs(node.left);
    const [rr, rs] = dfs(node.right);
    return [node.val + ls + rs, Math.max(lr, ls) + Math.max(rr, rs)];
  };
  return Math.max(...dfs(root));
}

// LeetCode 124 Binary Tree Maximum Path Sum.
function maxPathSum(root) {
  let best = -Infinity;
  const down = (node) => {
    if (!node) return 0;
    const l = Math.max(0, down(node.left));
    const r = Math.max(0, down(node.right));
    best = Math.max(best, node.val + l + r);   // bends here: record, do not return
    return node.val + Math.max(l, r);          // straight down: parent can extend
  };
  down(root);
  return best;
}

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def rob(root):
    """LeetCode 337 House Robber III: each node returns (rob_it, skip_it)."""
    def dfs(node):
        if not node:
            return 0, 0
        lr, ls = dfs(node.left)
        rr, rs = dfs(node.right)
        return node.val + ls + rs, max(lr, ls) + max(rr, rs)
    return max(dfs(root))

def max_path_sum(root):
    """LeetCode 124: return the best downward path, record the best bent path."""
    best = float("-inf")
    def down(node):
        nonlocal best
        if not node:
            return 0
        left = max(0, down(node.left))
        right = max(0, down(node.right))
        best = max(best, node.val + left + right)   # path bending at node
        return node.val + max(left, right)          # extendable by the parent
    down(root)
    return best

def min_camera_cover(root):
    """LeetCode 968: states 0 = needs cover, 1 = covered, 2 = camera."""
    cameras = 0
    def dfs(node):
        nonlocal cameras
        if not node:
            return 1
        l, r = dfs(node.left), dfs(node.right)
        if l == 0 or r == 0:
            cameras += 1
            return 2
        return 1 if l == 2 or r == 2 else 0
    root_state = dfs(root)                          # run first: it updates `cameras`
    return cameras + (root_state == 0)

def sum_of_distances_in_tree(n, edges):
    """LeetCode 834 with rerooting; iterative to survive deep trees."""
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    parent, order, stack = [-1] * n, [], [0]
    seen = [False] * n
    seen[0] = True
    while stack:                                    # preorder from root 0
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                parent[v] = u
                stack.append(v)
    count, ans = [1] * n, [0] * n
    for u in reversed(order):                       # children before parents
        p = parent[u]
        if p >= 0:
            count[p] += count[u]
            ans[p] += ans[u] + count[u]
    for u in order[1:]:                             # parents before children
        ans[u] = ans[parent[u]] - count[u] + (n - count[u])
    return ans

// LeetCode 337 House Robber III.
static int rob(TreeNode root) {
    int[] r = dfs(root);
    return Math.max(r[0], r[1]);
}
static int[] dfs(TreeNode node) {              // {robThis, skipThis}
    if (node == null) return new int[]{0, 0};
    int[] l = dfs(node.left), r = dfs(node.right);
    int robThis = node.val + l[1] + r[1];
    int skipThis = Math.max(l[0], l[1]) + Math.max(r[0], r[1]);
    return new int[]{robThis, skipThis};
}

// LeetCode 968 Binary Tree Cameras.
static int cameras;
static int minCameraCover(TreeNode root) {
    cameras = 0;
    return (state(root) == 0 ? 1 : 0) + cameras;
}
static int state(TreeNode node) {              // 0 needs cover, 1 covered, 2 camera
    if (node == null) return 1;
    int l = state(node.left), r = state(node.right);
    if (l == 0 || r == 0) { cameras++; return 2; }
    return (l == 2 || r == 2) ? 1 : 0;
}

// LeetCode 543 Diameter of Binary Tree: return height, record left + right.
int diameterOfBinaryTree(TreeNode* root) {
    int best = 0;
    function<int(TreeNode*)> height = [&](TreeNode* node) -> int {
        if (!node) return 0;
        int l = height(node->left), r = height(node->right);
        best = max(best, l + r);               // edges on the path bending here
        return 1 + max(l, r);
    };
    height(root);
    return best;
}
